using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;
using Microsoft.Agents.AI.ChatCompletion;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

builder.Services.AddSingleton<ResearchTools>();
builder.Services.AddSingleton<NoteService>();

var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();
var noteService = host.Services.GetRequiredService<NoteService>();

// Build the agent with tools
var agent = new ChatClientAgent(
    chatClient,
    "ResearchAgent",
    "You are a research assistant. Use the web_search tool to find information about the "
    + "requested topic. Use the take_note tool to record key findings as you go. "
    + "After gathering enough information, provide a comprehensive summary of your findings "
    + "including all notes you have taken.",
    [researchTools, noteService]);

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and summarize your findings: {topic}")
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 10,
};

await foreach (var message in agent.InvokeStreamingAsync(history, options))
{
    if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
    {
        Console.Write(message.Text);
    }
}

Console.WriteLine("\n\n=== Notes Taken ===");
foreach (var note in noteService.GetNotes())
{
    Console.WriteLine($"  • {note}");
}

// --- Tool Definitions ---

public sealed class ResearchTools
{
    private static readonly HttpClient Http = new();

    [Description("Search the web for information about a query. Returns a list of relevant results with titles and snippets.")]
    [McpToolName("web_search")]
    public async Task<string> WebSearchAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (default 5)")] int maxResults = 5)
    {
        // Uses DuckDuckGo Instant Answer API as a free web search source
        var encoded = Uri.EscapeDataString(query);
        var url = $"https://api.duckduckgo.com/?q={encoded}&format=json&no_html=1&skip_disambig=1";

        try
        {
            var response = await Http.GetFromJsonAsync<JsonElement>(url);
            var results = new List<string>();

            // Extract abstract
            var abstractText = response.GetProperty("AbstractText").GetString();
            if (!string.IsNullOrEmpty(abstractText))
            {
                var source = response.GetProperty("AbstractSource").GetString();
                results.Add($"[{source}] {abstractText}");
            }

            // Extract related topics
            if (response.TryGetProperty("RelatedTopics", out var topics))
            {
                foreach (var item in topics.EnumerateArray().Take(maxResults))
                {
                    if (item.TryGetProperty("Text", out var text))
                    {
                        results.Add(text.GetString() ?? "");
                    }
                }
            }

            return results.Count > 0
                ? string.Join("\n\n", results)
                : $"No results found for '{query}'. Try a different search term.";
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}. Try a different query.";
        }
    }
}

public sealed class NoteService
{
    private readonly List<string> _notes = [];

    [Description("Save a note capturing a key finding from your research. Use this to record important facts, statistics, or insights discovered during web searches.")]
    [McpToolName("take_note")]
    public string TakeNote(
        [Description("The content of the note to save")] string content)
    {
        _notes.Add(content);
        return $"Note #{_notes.Count} saved: {content}";
    }

    public IReadOnlyList<string> GetNotes() => _notes.AsReadOnly();
}

